function basename(pathValue) {
  const rawPath = String(pathValue || "");
  const parts = rawPath.split(/[/\\]+/);
  return parts[parts.length - 1] || "test12.mjs";
}

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function buildHelp(programName) {
  return `${buildUsage(programName)}

options:
  -h, --help  show this help message and exit
  --a A       Comma-separated items
  --b B       Unit name
`;
}

function isNegativeNumberToken(token) {
  return /^-\d+(?:\.\d+)?$/.test(token) || /^-\.\d+$/.test(token);
}

function looksLikeOption(token) {
  if (token === undefined || token === "-") {
    return false;
  }

  if (token === "--") {
    return true;
  }

  if (!token.startsWith("-")) {
    return false;
  }

  return !isNegativeNumberToken(token);
}

class CliParseError extends Error {
  constructor(message) {
    super(message);
    this.name = "CliParseError";
  }
}

export function parseTest12Args(argv) {
  let a;
  let b;
  const extras = [];

  for (let index = 0; index < argv.length; ) {
    const token = argv[index];

    if (token === "-h" || token === "--help") {
      return { help: true };
    }

    if (token === "--") {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token === "--a") {
      const nextToken = argv[index + 1];
      if (nextToken === undefined || looksLikeOption(nextToken)) {
        throw new CliParseError("argument --a: expected one argument");
      }
      a = nextToken;
      index += 2;
      continue;
    }

    if (token.startsWith("--a=")) {
      a = token.slice(4);
      index += 1;
      continue;
    }

    if (token === "--b") {
      const nextToken = argv[index + 1];
      if (nextToken === undefined || looksLikeOption(nextToken)) {
        throw new CliParseError("argument --b: expected one argument");
      }
      b = nextToken;
      index += 2;
      continue;
    }

    if (token.startsWith("--b=")) {
      b = token.slice(4);
      index += 1;
      continue;
    }

    extras.push(token);
    index += 1;
  }

  if (extras.length > 0) {
    throw new CliParseError(`unrecognized arguments: ${extras.join(" ")}`);
  }

  const missing = [];
  if (a === undefined) {
    missing.push("--a");
  }
  if (b === undefined) {
    missing.push("--b");
  }

  if (missing.length > 0) {
    throw new CliParseError(`the following arguments are required: ${missing.join(", ")}`);
  }

  return { help: false, a, b };
}

export function runTest12Cli(main, argv = process.argv, io = process) {
  const programName = basename(argv[1]);
  let parsedArgs;

  try {
    parsedArgs = parseTest12Args(argv.slice(2));
  } catch (error) {
    if (!(error instanceof CliParseError)) {
      throw error;
    }

    io.stderr.write(`${buildUsage(programName)}\n`);
    io.stderr.write(`${programName}: error: ${error.message}\n`);
    io.exitCode = 2;
    return;
  }

  if (parsedArgs.help) {
    io.stdout.write(buildHelp(programName));
    return;
  }

  main(parsedArgs, io);
}

export { buildHelp, buildUsage };

