import { pluralize } from "./inflection.mjs";

function normalizeWord(word) {
  if (word === null || word === undefined) {
    return "";
  }
  return String(word);
}

function getCount(value) {
  if (typeof value === "number") {
    return value;
  }

  if (value === null || value === undefined) {
    return 0;
  }

  if (typeof value.length === "number") {
    return value.length;
  }

  if (typeof value.size === "number") {
    return value.size;
  }

  return Array.from(value).length;
}

export function cardinalize(unit, count) {
  const word = normalizeWord(unit);
  return count === 1 ? word : pluralize(word);
}

export function unitLen(value, unit) {
  const count = getCount(value);
  const word = count === 1 ? normalizeWord(unit) : cardinalize(unit, count);

  if (count === 0) {
    return `No ${cardinalize(unit, 0)}`;
  }

  return `${count} ${word}`;
}

