function isTitleCase(value) {
  if (value.length === 0) {
    return false;
  }

  const first = value[0];
  const rest = value.slice(1);
  return first === first.toUpperCase() && rest === rest.toLowerCase();
}

export function applyWordCase(sourceWord, lowerCaseWord) {
